// decidir si ha cambiado de DIA se sigue usando la hora del servidor
// (new Date()), no metadata.ts, por el mismo motivo de siempre: una Pila
// concreta puede cruzar la medianoche antes que las demas.
var tsAhora = new Date().getTime();
var diaHoy = fechaLocal(tsAhora);
var tsLectura = metadata.ts ? parseInt(metadata.ts) : tsAhora;

var valorActual = parseFloat(msg.caudal_Sum);
if (isNaN(valorActual)) {
    return { msg: {}, metadata: metadata, msgType: "POST_TELEMETRY_REQUEST" };
}

var estadoPrevio = null;
try {
    estadoPrevio = metadata.ss_cf_state ? JSON.parse(metadata.ss_cf_state) : null;
} catch (e) { estadoPrevio = null; }

var mensajes = [];
var nuevoEstado;

if (!estadoPrevio) {
    // Primera lectura de siempre (o tras subir este arreglo) -- no hay
    // valor anterior que ponderar todavia, solo arrancamos el estado.
    nuevoEstado = { ultimoValor: valorActual, ultimoTs: tsLectura, sumaPonderada: 0, tiempoAcumulado: 0, dia: diaHoy };

} else if (estadoPrevio.dia !== diaHoy) {
    // Cambio de dia: cerramos el dia anterior. El ULTIMO valor conocido
    // sigue vigente hasta el final de ese dia (23:59:59), asi que se
    // pondera tambien ese ultimo tramo antes de calcular la media final.
    var finAnterior = finDeDiaTs(estadoPrevio.dia, tsAhora);
    var gapCierre = Math.max(0, finAnterior - estadoPrevio.ultimoTs);
    var sumaFinal = estadoPrevio.sumaPonderada + (estadoPrevio.ultimoValor * gapCierre);
    var tiempoFinal = estadoPrevio.tiempoAcumulado + gapCierre;

    if (tiempoFinal > 0) {
        var mediaCierre = Math.round((sumaFinal / tiempoFinal) * 100) / 100;
        var inicioTs = inicioDeDiaTs(estadoPrevio.dia, tsAhora);

        var metaInicio = metadata;
        var metaFin = JSON.parse(JSON.stringify(metadata));
        metaInicio.ts = String(inicioTs);
        metaFin.ts = String(finAnterior);

        var msgCierre = {};
        msgCierre["caudal_fijado"] = mediaCierre;

        mensajes.push({ msg: msgCierre, metadata: metaInicio, msgType: "POST_TELEMETRY_REQUEST" });
        mensajes.push({ msg: msgCierre, metadata: metaFin, msgType: "POST_TELEMETRY_REQUEST" });
    }

    // Arrancamos el nuevo dia desde cero, con esta lectura como punto de partida.
    nuevoEstado = { ultimoValor: valorActual, ultimoTs: tsLectura, sumaPonderada: 0, tiempoAcumulado: 0, dia: diaHoy };

} else {
    // Mismo dia: se pondera el valor ANTERIOR por el tiempo que ha estado
    // vigente hasta AHORA (hasta que llega este nuevo dato).
    var gap = Math.max(0, tsLectura - estadoPrevio.ultimoTs);
    nuevoEstado = {
        ultimoValor: valorActual,
        ultimoTs: tsLectura,
        sumaPonderada: estadoPrevio.sumaPonderada + (estadoPrevio.ultimoValor * gap),
        tiempoAcumulado: estadoPrevio.tiempoAcumulado + gap,
        dia: diaHoy
    };
}

metadata.acc_atributos_nuevos = JSON.stringify({ "cf_state": JSON.stringify(nuevoEstado) });

if (mensajes.length === 0) {
    mensajes.push({ msg: {}, metadata: metadata, msgType: "POST_TELEMETRY_REQUEST" });
}

return mensajes;

function parseObj(value) {
    if (!value) { return {}; }
    if (typeof value === "string") {
        try { return JSON.parse(value); } catch (e) { return {}; }
    }
    if (typeof value === "object") { return value; }
    return {};
}

var mapaValores = parseObj(metadata.ss_mapa_caudal_operaciones);
var mapaDiario  = parseObj(metadata.ss_mapa_caudal_operaciones_diario);
var mapaAnual   = parseObj(metadata.ss_mapa_caudal_operaciones_anual);
var mapaTotal   = parseObj(metadata.ss_mapa_caudal_operaciones_total_m3);
var signos = parseObj(metadata.ss_operaciones_caudalimetros);

var nombreCaudalimetro = Object.keys(msg)[0];
var valorCrudo = parseFloat(msg[nombreCaudalimetro]);

if (nombreCaudalimetro && !isNaN(valorCrudo)) {
    var signo = (signos[nombreCaudalimetro] === "resta") ? -1 : 1;
    mapaValores[nombreCaudalimetro] = Math.round(valorCrudo * signo * 1000) / 1000;

    var diario = parseFloat(metadata.civ_caudal_total_diario_m3);
    if (!isNaN(diario)) { mapaDiario[nombreCaudalimetro] = Math.round(diario * signo * 1000) / 1000; }

    var anual = parseFloat(metadata.civ_caudal_total_anual_m3);
    if (!isNaN(anual)) { mapaAnual[nombreCaudalimetro] = Math.round(anual * signo * 1000) / 1000; }

    var total = parseFloat(metadata.civ_caudal_total_m3);
    if (!isNaN(total)) { mapaTotal[nombreCaudalimetro] = Math.round(total * signo * 1000) / 1000; }
}

function sumarMapa(mapa) {
    var s = 0;
    for (var k in mapa) { if (mapa.hasOwnProperty(k)) { s += mapa[k]; } }
    return Math.round(s * 1000) / 1000;
}

metadata.caudal_operaciones_total = String(sumarMapa(mapaValores));
metadata.caudal_operaciones_diario_total = String(sumarMapa(mapaDiario));
metadata.caudal_operaciones_anual_total = String(sumarMapa(mapaAnual));
metadata.caudal_operaciones_total_m3_total = String(sumarMapa(mapaTotal));

return {
    msg: {
        mapa_caudal_operaciones: JSON.stringify(mapaValores),
        mapa_caudal_operaciones_diario: JSON.stringify(mapaDiario),
        mapa_caudal_operaciones_anual: JSON.stringify(mapaAnual),
        mapa_caudal_operaciones_total_m3: JSON.stringify(mapaTotal)
    },
    metadata: metadata,
    msgType: "POST_ATTRIBUTES_REQUEST"
};

return {
    msg: {
        ajuste_resta_otro_grupo: msg.ajuste_resta_otro_grupo || 0,
        ajuste_resta_otro_grupo_diario_m3: msg.ajuste_resta_otro_grupo_diario_m3 || 0
    },
    metadata: metadata,
    msgType: "POST_ATTRIBUTES_REQUEST"
};

// FIX 2026-10-06 -- caudal_Sum y volumenes del Grupo_Riego, calculados en
// UN SOLO mensaje por grupo y trama (sin carreras entre caudalimetros):
//  - msg.desglose_caudalimetros trae, SIN signo, el caudal (c) y los
//    volumenes diario (d), anual (a) y total (t) de cada caudalimetro del
//    grupo, todos de la MISMA trama.
//  - El signo +Suma/-Resta se lee del propio Grupo_Riego (atributo
//    "operaciones_caudalimetros", el que guarda el widget), cargado en el
//    nodo anterior. Por defecto "suma".
//  - Piso a 0 (igual que en la rama v3): si los caudalimetros en resta
//    pesan mas que los de suma, el caudal y los volumenes del grupo dan 0,
//    nunca negativo.
// Sustituye a la rama v3 ("Actualizar mapa caudal_operaciones" ->
// "Preparar telemetria caudal_operaciones (GR) v3"), que actualizaba un
// mapa compartido caudalimetro a caudalimetro: con varios caudalimetros en
// la misma trama se pisaban entre si y el total podia salir mal justo al
// cambiar un signo (p.ej. Bujalmoro con todos en resta dio +2 l/s).
function r3(x) { return Math.round(x * 1000) / 1000; }
function parseObj(value) {
    if (!value) { return {}; }
    if (typeof value === "string") {
        try { return JSON.parse(value); } catch (e) { return {}; }
    }
    if (typeof value === "object") { return value; }
    return {};
}

var signos = parseObj(metadata.ss_operaciones_caudalimetros);
var desglose = parseObj(msg.desglose_caudalimetros);

var caudal = 0, diario = 0, anual = 0, total = 0, hay = false;
for (var nombre in desglose) {
    if (!desglose.hasOwnProperty(nombre)) { continue; }
    var it = desglose[nombre] || {};
    var signo = (signos[nombre] === "resta") ? -1 : 1;
    var vc = parseFloat(it.c), vd = parseFloat(it.d), va = parseFloat(it.a), vt = parseFloat(it.t);
    if (!isNaN(vc)) { caudal += signo * vc; hay = true; }
    if (!isNaN(vd)) { diario += signo * vd; }
    if (!isNaN(va)) { anual += signo * va; }
    if (!isNaN(vt)) { total += signo * vt; }
}

if (!hay) {
    // Trama sin desglose (no deberia pasar): se usa el total que trae la
    // trama tal cual, para no dejar el grupo sin dato.
    caudal = parseFloat(msg.caudal_Sum_v2) || 0;
    diario = parseFloat(msg.caudal_total_diario_m3_v2) || 0;
    anual = parseFloat(msg.caudal_total_anual_m3_v2) || 0;
    total = parseFloat(msg.caudal_total_m3_v2) || 0;
}

// Ajuste de cruce entre grupos (La Española - La Española Desembalse)
var ajuste = parseFloat(metadata.ss_ajuste_resta_otro_grupo);
var ajusteDiario = parseFloat(metadata.ss_ajuste_resta_otro_grupo_diario_m3);
if (!isNaN(ajuste) && ajuste !== 0) { caudal = caudal - ajuste; }
if (!isNaN(ajusteDiario) && ajusteDiario !== 0) { diario = diario - ajusteDiario; }

var salida = {
    caudal_Sum: r3(caudal),
    caudal_total_diario_m3: r3(diario),
    caudal_total_anual_m3: r3(anual),
    caudal_total_m3: r3(total)
};

// Piso a 0: el caudal y los volumenes del grupo nunca son negativos.
salida.caudal_Sum = Math.max(0, salida.caudal_Sum);
salida.caudal_total_diario_m3 = Math.max(0, salida.caudal_total_diario_m3);
salida.caudal_total_anual_m3 = Math.max(0, salida.caudal_total_anual_m3);
salida.caudal_total_m3 = Math.max(0, salida.caudal_total_m3);

return { msg: salida, metadata: metadata, msgType: "POST_TELEMETRY_REQUEST" };

var lista = [];
try {
    lista = JSON.parse(metadata.cu_lista_json || "[]");
} catch (e) {
    lista = [];
}
return { msg: lista, metadata: metadata, msgType: msgType };

function sanitizeKey(nombre) {
    var desde = "áéíóúÁÉÍÓÚüÜñÑàèìòùÀÈÌÒÙâêîôûÂÊÎÔÛäëïöÄËÏÖ";
    var hasta = "aeiouAEIOUuUnNaeiouAEIOUaeiouAEIOUaeioAEIO";
    var out = "";
    var str = String(nombre);
    for (var i = 0; i < str.length; i++) {
        var ch = str.charAt(i);
        var idx = desde.indexOf(ch);
        out += (idx !== -1) ? hasta.charAt(idx) : ch;
    }
    out = out.toLowerCase();
    var limpio = "";
    for (var j = 0; j < out.length; j++) {
        var c = out.charAt(j);
        if ((c >= "a" && c <= "z") || (c >= "0" && c <= "9")) {
            limpio += c;
        } else {
            limpio += "_";
        }
    }
    while (limpio.indexOf("__") !== -1) { limpio = limpio.replace("__", "_"); }
    while (limpio.charAt(0) === "_") { limpio = limpio.slice(1); }
    while (limpio.charAt(limpio.length - 1) === "_") { limpio = limpio.slice(0, -1); }
    return "cu_" + limpio;
}

var clave = sanitizeKey(msg.nombre);
var valor = {
    valor: msg.valor,
    sector: msg.sector,
    ts: msg.ts
};

var salida = {};
salida[clave] = JSON.stringify(valor);

return {
    msg: salida,
    metadata: metadata,
    msgType: "POST_ATTRIBUTES_REQUEST"
};

function r3(x) { return Math.round(x * 1000) / 1000; }

// Estos 4 valores YA vienen bien calculados (con el signo leido de
// verdad del Grupo_Riego, en el nodo "Actualizar mapa caudal_operaciones")
// -- solo hacia falta publicarlos como telemetria de verdad, cosa que
// antes no hacia nadie (el nodo siguiente, "Guardar mapa_caudal_operaciones
// (GR)", solo los guardaba como atributos de diagnostico).
var salida = {
    caudal_Sum: parseFloat(metadata.caudal_operaciones_total) || 0,
    caudal_total_diario_m3: parseFloat(metadata.caudal_operaciones_diario_total) || 0,
    caudal_total_anual_m3: parseFloat(metadata.caudal_operaciones_anual_total) || 0,
    caudal_total_m3: parseFloat(metadata.caudal_operaciones_total_m3_total) || 0
};

// Ajuste de cruce entre grupos (La Española - La Española Desembalse),
// aplicado aqui sobre el total YA bien firmado (antes se aplicaba sobre
// el total con el signo mal leido, en "Aplicar ajuste y preparar
// telemetria v2").
var ajuste = parseFloat(metadata.ss_ajuste_resta_otro_grupo);
var ajusteDiario = parseFloat(metadata.ss_ajuste_resta_otro_grupo_diario_m3);
if (!isNaN(ajuste) && ajuste !== 0) { salida.caudal_Sum = r3(salida.caudal_Sum - ajuste); }
if (!isNaN(ajusteDiario) && ajusteDiario !== 0) { salida.caudal_total_diario_m3 = r3(salida.caudal_total_diario_m3 - ajusteDiario); }

// Piso a 0: una resta mal calibrada no debe dar caudal ni volumen negativo
// (igual que ya se hacia en la rama v2 antigua).
salida.caudal_Sum = Math.max(0, salida.caudal_Sum);
salida.caudal_total_diario_m3 = Math.max(0, salida.caudal_total_diario_m3);
salida.caudal_total_anual_m3 = Math.max(0, salida.caudal_total_anual_m3);
salida.caudal_total_m3 = Math.max(0, salida.caudal_total_m3);

return { msg: salida, metadata: metadata, msgType: "POST_TELEMETRY_REQUEST" };
